    /**
     * Ticks the script ran (the final geometry tick included).
     */
    public var ticks: UInt64
    /**
     * Step the script stopped at (`until` out of time, a rejected input, unreadable JSON).
     */
    public var stoppedStep: UInt32?
    /**
     * Why it stopped; `None` = it ran to the end.
     */
    public var stoppedReason: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Final value of every pointer the script's ticks wrote — apply it like one tick.
         */tick: TickResult, 
