         */ticks: UInt64, 
        /**
         * Step the script stopped at (`until` out of time, a rejected input, unreadable JSON).
         */stoppedStep: UInt32?, 
        /**
         * Why it stopped; `None` = it ran to the end.
         */stoppedReason: String?) {
        self.tick = tick
        self.ticks = ticks
        self.stoppedStep = stoppedStep
        self.stoppedReason = stoppedReason
    }
}



