        self.eyeX = eyeX
        self.eyeY = eyeY
        self.eyeZ = eyeZ
        self.targetX = targetX
        self.targetY = targetY
        self.targetZ = targetZ
        self.yfov = yfov
        self.near = near
        self.far = far
        self.focusDistance = focusDistance
        self.orbitDistance = orbitDistance
    }
}



