/**
 * Coarse eval diagnostic category exposed to Swift / Kotlin.
 */

public enum EvalDiagnosticKind {
    
    case unknownIdentifier
    case unknownFunction
    case typeMismatch
    case arityMismatch
    case arrayLengthMismatch
    /**
     * Built-in received a value outside its domain (`sqrt(-1)`, `mod(x, 0)`).
     */
    case domainError
    /**
     * Procedural generator failed to evaluate.
     */
    case generator
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEvalDiagnosticKind: FfiConverterRustBuffer {
    typealias SwiftType = EvalDiagnosticKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EvalDiagnosticKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .unknownIdentifier
        
        case 2: return .unknownFunction
        
        case 3: return .typeMismatch
        
        case 4: return .arityMismatch
        
        case 5: return .arrayLengthMismatch
        
        case 6: return .domainError
        
        case 7: return .generator
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: EvalDiagnosticKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .unknownIdentifier:
            writeInt(&buf, Int32(1))
        
        
        case .unknownFunction:
            writeInt(&buf, Int32(2))
        
        
        case .typeMismatch:
            writeInt(&buf, Int32(3))
        
        
        case .arityMismatch:
            writeInt(&buf, Int32(4))
        
        
        case .arrayLengthMismatch:
            writeInt(&buf, Int32(5))
        
        
        case .domainError:
            writeInt(&buf, Int32(6))
        
        
        case .generator:
            writeInt(&buf, Int32(7))
        
        }
    }
}


