/**
 * Unified error type surfaced across the FFI boundary.
 *
 * `tride-runtime-api` exposes three distinct error enums (`LoadError`,
 * `InputError`, `TriggerError`); we collapse them into one
 * foreign-facing enum because Swift / Kotlin throwing functions
 * share a single error type per call site and a single FFI enum
 * keeps the bindings ergonomic. The original variant is preserved
 * in the `msg` field of every variant.
 */
public enum TrideError {

    
    
    /**
     * `.trd` archive parse / schema / bindings / SM compile failure.
     */
    case LoadFailed(message: String)
    
    /**
     * The `.trd` was written by a newer Tride format and does not parse here: the file is fine,
     * the app is old — ask to update it rather than report a broken file. The
     * message names both format versions.
     */
    case NewerFormat(message: String)
    
    /**
     * Unknown view-model name or type mismatch on `setBinding` / `getBinding`.
     */
    case InvalidBinding(message: String)
    
    /**
     * Unknown event name or non-trigger kind on `trigger`.
     */
    case InvalidTrigger(message: String)
    
    /**
     * Internal runtime invariant violated (mutex poisoned, JSON encode
     * failure, …). Should never happen in practice; logged for
     * observability.
     */
    case Internal(message: String)
    
    /**
     * [`RuntimeHandle::emit_event`] / manifest `events[]` contract.
     */
    case OutgoingEvent(message: String)
    
    /**
     * A host audio call that cannot be applied: an input name that is no slug or was never
     * begun, a format without samples, a time or gain that is not finite.
     */
    case InvalidAudio(message: String)
    
    /**
     * A host picture call that cannot be applied: a name that is no image input, a size outside
     * 1…2048 px a side.
     */
    case InvalidImage(message: String)
    
    /**
     * A host scroll report that cannot be applied: a value that is not finite, a window height
     * of 0 or less, a negative scene height. The frame the scene had stays.
     */
    case InvalidScroll(message: String)
    
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTrideError: FfiConverterRustBuffer {
    typealias SwiftType = TrideError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TrideError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .LoadFailed(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .NewerFormat(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .InvalidBinding(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .InvalidTrigger(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .Internal(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .OutgoingEvent(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .InvalidAudio(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .InvalidImage(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .InvalidScroll(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TrideError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .LoadFailed(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .NewerFormat(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .InvalidBinding(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .InvalidTrigger(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .Internal(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .OutgoingEvent(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))
        case .InvalidAudio(_ /* message is ignored*/):
            writeInt(&buf, Int32(7))
        case .InvalidImage(_ /* message is ignored*/):
            writeInt(&buf, Int32(8))
        case .InvalidScroll(_ /* message is ignored*/):
            writeInt(&buf, Int32(9))

        
        }
    }
}


