/**
 * Typed mutation payload — eliminates JSON encode/decode overhead per tick.
 *
 * Swift codegen produces a tagged enum:
 * ```swift
 * public enum TrideTypedValue {
 * case scalar(value: Double)
 * case vec3(x: Double, y: Double, z: Double)
 * case quat(x: Double, y: Double, z: Double, w: Double)
 * case color(r: Double, g: Double, b: Double, a: Double)
 * case boolValue(value: Bool)
 * case stringValue(value: String)
 * case json(raw: String)
 * }
 * ```
 */

public enum TrideTypedValue {
    
    /**
     * Floating-point scalar (single number property).
     */
    case scalar(value: Double
    )
    /**
     * Three-component vector (translation, scale).
     */
    case vec3(x: Double, y: Double, z: Double
    )
    /**
     * Unit quaternion `[x, y, z, w]` (canonical rotation).
     */
    case quat(x: Double, y: Double, z: Double, w: Double
    )
    /**
     * RGBA color `[r, g, b, a]`.
     */
    case color(r: Double, g: Double, b: Double, a: Double
    )
    /**
     * Boolean property.
     */
    case boolValue(value: Bool
    )
    /**
     * String property.
     */
    case stringValue(value: String
    )
    /**
     * Fallback: raw JSON for shapes not yet covered by typed variants.
     */
    case json(raw: String
    )
}


