        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .scalar(value: try FfiConverterDouble.read(from: &buf)
        )
        
        case 2: return .vec3(x: try FfiConverterDouble.read(from: &buf), y: try FfiConverterDouble.read(from: &buf), z: try FfiConverterDouble.read(from: &buf)
        )
        
        case 3: return .quat(x: try FfiConverterDouble.read(from: &buf), y: try FfiConverterDouble.read(from: &buf), z: try FfiConverterDouble.read(from: &buf), w: try FfiConverterDouble.read(from: &buf)
        )
        
        case 4: return .color(r: try FfiConverterDouble.read(from: &buf), g: try FfiConverterDouble.read(from: &buf), b: try FfiConverterDouble.read(from: &buf), a: try FfiConverterDouble.read(from: &buf)
        )
        
        case 5: return .boolValue(value: try FfiConverterBool.read(from: &buf)
        )
        
        case 6: return .stringValue(value: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .json(raw: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TrideTypedValue, into buf: inout [UInt8]) {
        switch value {
        
        
