            FfiConverterDouble.write(r, into: &buf)
            FfiConverterDouble.write(g, into: &buf)
            FfiConverterDouble.write(b, into: &buf)
            FfiConverterDouble.write(a, into: &buf)
            
        
        case let .boolValue(value):
            writeInt(&buf, Int32(5))
            FfiConverterBool.write(value, into: &buf)
            
        
        case let .stringValue(value):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(value, into: &buf)
            
        
        case let .json(raw):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(raw, into: &buf)
            
        }
    }
