/**
 * Foreign callback for [`TrideStateChange`]s — one call per layer that transitioned, in layer
 * order, before that layer's state / transition actions report their events.
 */
public protocol TrideLayerStateChangeListener : AnyObject {
    
    func onLayerStateChange(change: TrideStateChange) 
    
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
private let IDX_CALLBACK_FREE: Int32 = 0
// Callback return codes
private let UNIFFI_CALLBACK_SUCCESS: Int32 = 0
private let UNIFFI_CALLBACK_ERROR: Int32 = 1
private let UNIFFI_CALLBACK_UNEXPECTED_ERROR: Int32 = 2

// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceTrideLayerStateChangeListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    static var vtable: UniffiVTableCallbackInterfaceTrideLayerStateChangeListener = UniffiVTableCallbackInterfaceTrideLayerStateChangeListener(
        onLayerStateChange: { (
            uniffiHandle: UInt64,
            change: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceTrideLayerStateChangeListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onLayerStateChange(
                     change: try FfiConverterTypeTrideStateChange.lift(change)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterCallbackInterfaceTrideLayerStateChangeListener.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface TrideLayerStateChangeListener: handle missing in uniffiFree")
            }
        }
    )
}

private func uniffiCallbackInitTrideLayerStateChangeListener() {
    uniffi_tride_ffi_fn_init_callback_vtable_tridelayerstatechangelistener(&UniffiCallbackInterfaceTrideLayerStateChangeListener.vtable)
}

